import type { ProductDefinition } from '../model'
import { P } from './dsl'

// Displays, projection, LED, signal distribution/AV-over-IP, control.

type S = Parameters<typeof P>[5]
const proj = (maker: string, model: string, summary: string, io: string, w: number, spec: S = {}) => P(maker, model, 'projector', summary, io, { mount: 'ceiling', w, ...spec })
const disp = (maker: string, model: string, summary: string, io: string, w: number, spec: S = {}) => P(maker, model, 'display', summary, io, { mount: 'wall', w, ...spec })
const led = (maker: string, model: string, summary: string, w = 150, spec: S = {}) => P(maker, model, 'display', summary, 'ethercon:Data In, ethercon:Data Thru, true1In, true1Out', { mount: 'truss', w, kg: 8, tags: 'led tile', ...spec })
const ledProc = (maker: string, model: string, summary: string, io: string, spec: S = {}) => P(maker, model, 'ledProcessor', summary, io, { ru: 1, ...spec })
const sw = (maker: string, model: string, summary: string, io: string, spec: S = {}) => P(maker, model, 'matrixSwitcher', summary, io, { ru: 1, ...spec })
const ext = (maker: string, model: string, summary: string, io: string, spec: S = {}) => P(maker, model, 'extender', summary, io, { mount: 'shelf', ...spec })
const enc = (maker: string, model: string, summary: string, io: string, spec: S = {}) => P(maker, model, 'encoder', summary, io, { mount: 'shelf', ...spec })
const dec = (maker: string, model: string, summary: string, io: string, spec: S = {}) => P(maker, model, 'decoder', summary, io, { mount: 'shelf', ...spec })
const cp = (maker: string, model: string, summary: string, io: string, spec: S = {}) => P(maker, model, 'controlProcessor', summary, io, { mount: 'shelf', ...spec })
const tp = (maker: string, model: string, summary: string, spec: S = {}, io = 'lan, poe') => P(maker, model, 'touchPanel', summary, io, { mount: 'wall', ...spec })

